INSERT INTO `patient` VALUES (1,'黎明','','',1,'2026-04-04 18:07:28','2026-04-04 18:07:28'),(2,'赵国强','确诊冠状动脉粥样硬化性心脏病（CAD）5 年。\n\n高血压病史 10 年，长期服用苯磺酸氨氯地平。\n\n2023 年曾进行过冠状动脉造影，显示左前降支（LAD）50% 狭窄。','患者近期主诉在快速行走或爬坡时出现胸骨后压榨性疼痛，休息 3-5 分钟后可缓解。心电图示窦性心律，ST 段轻度压低。建议严格控制低盐低脂饮食，维持目前的抗血小板及调脂治疗（阿司匹林+他汀），并加用 β 受体阻滞剂以控制心率。嘱患者随身携带硝酸甘油。',2,'2026-04-04 21:23:44','2026-04-04 21:23:44'),(3,'李四','脑卒中发病','脑卒中发病，持续高烧多日',5,'2026-04-07 15:58:05','2026-04-07 15:58:05'),(4,'哈机密','喜欢哈气','按时投喂猫条',6,'2026-04-08 13:54:58','2026-04-08 13:54:58'),(6,'李明','','',7,'2026-04-09 11:18:20','2026-04-09 11:18:20'),(7,'网络卡','','',7,'2026-04-09 12:43:46','2026-04-09 12:43:46'),(9,'李建国','既往有高血压10年，未规律服药；2型糖尿病5年。今晨突发右侧肢体无力、言语不清，发病约2小时入院。无外伤史。无癫痫病史。','考虑急性脑梗死，建议立即完善头颅CT排除出血，评估是否符合静脉溶栓指征，监测血压血糖。',8,'2026-04-09 16:56:39','2026-04-09 16:56:39'),(10,'王秀兰','长期高血压病史15年，血压控制不佳。突发剧烈头痛伴呕吐，随后出现意识模糊约1小时。无明显外伤。','高度怀疑脑出血，建议紧急头颅CT检查，控制血压，必要时神经外科会诊评估手术指征。',8,'2026-04-09 16:57:12','2026-04-09 16:57:12'),(11,'张伟','男性，55岁，有高血压8年、吸烟史30年（每日1包），血脂偏高，偶有头晕，无明确卒中史。近期体检发现颈动脉斑块。','脑卒中高危人群，建议控制血压、戒烟、他汀类降脂治疗，必要时抗血小板治疗，定期复查。',8,'2026-04-09 16:57:47','2026-04-09 16:57:47');
